import random
import time


def retry_with_backoff(fn, attempts: int = 5, base_delay: float = 0.5, max_delay: float = 8.0,
                       retry_on: tuple[type[Exception], ...] = (ConnectionError, TimeoutError)):
    """Call fn, retrying transient errors with capped exponential backoff and jitter."""
    if attempts < 1:
        raise ValueError("attempts must be >= 1")
    for attempt in range(1, attempts + 1):
        try:
            return fn()
        except retry_on:
            if attempt == attempts:
                raise
            delay = min(max_delay, base_delay * 2 ** (attempt - 1))
            time.sleep(delay * random.uniform(0.5, 1.0))
